begin;
select no_plan();
select ok(not has_function_privilege('anon','loopkit.referral_credit_snapshot(uuid,text)','execute'),'anon cannot fetch host state');
select ok(not has_function_privilege('authenticated','loopkit.apply_referral_credit_checked(uuid,text,jsonb,jsonb,jsonb)','execute'),'clients cannot submit calculated state');
select ok(has_function_privilege('service_role','loopkit.apply_referral_credit_checked(uuid,text,jsonb,jsonb,jsonb)','execute'),'trusted service can compare and swap');
insert into auth.users(id,instance_id,aud,role,email)values('00490000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','referral-cas@test.local');
insert into loopkit.programs(id,vendor_id,type,name,stamps_required,reward_text,config,active)values('00490000-0000-0000-0000-000000000010','00490000-0000-0000-0000-000000000001','lucky','CAS test',8,'Coffee','{}',true);
insert into loopkit.cards(id,program_id,phone,state)values('00490000-0000-0000-0000-000000000020','00490000-0000-0000-0000-000000000010','+6591110049','{"visits_since_win":0,"total_wins":0}');
insert into loopkit.referral_hosts(id,vendor_id,program_id,host_phone,referral_code)values('00490000-0000-0000-0000-000000000030','00490000-0000-0000-0000-000000000001','00490000-0000-0000-0000-000000000010','+6591110049','cas-referral');
insert into loopkit.referral_credits(referral_host_id,guest_phone)values('00490000-0000-0000-0000-000000000030','+6592220049'),('00490000-0000-0000-0000-000000000030','+6593330049');
create temporary table snapshots(value jsonb);
insert into snapshots select loopkit.referral_credit_snapshot('00490000-0000-0000-0000-000000000030','+6592220049');
select ok(loopkit.apply_referral_credit_checked('00490000-0000-0000-0000-000000000030','+6592220049',(select value from snapshots),'{"visits_since_win":1,"total_wins":0}','{"won":false}'),'first snapshot applies');
select ok(not loopkit.apply_referral_credit_checked('00490000-0000-0000-0000-000000000030','+6593330049',(select value from snapshots),'{"visits_since_win":1,"total_wins":0}','{"won":false}'),'stale competing snapshot rejected');
select ok((select credited_at is null from loopkit.referral_credits where referral_host_id='00490000-0000-0000-0000-000000000030' and guest_phone='+6593330049'),'conflict does not consume credit');
select ok(loopkit.apply_referral_credit_checked('00490000-0000-0000-0000-000000000030','+6593330049',loopkit.referral_credit_snapshot('00490000-0000-0000-0000-000000000030','+6593330049'),'{"visits_since_win":2,"total_wins":0}','{"won":false}'),'fresh retry applies');
select is((select state->>'visits_since_win' from loopkit.cards where id='00490000-0000-0000-0000-000000000020'),'2','both guest credits retained');
select ok(loopkit.apply_referral_credit_checked('00490000-0000-0000-0000-000000000030','+6593330049','{}','{}','{}'),'already credited commit is idempotent');
select is(loopkit.referral_credit_snapshot('00490000-0000-0000-0000-000000000030','+6593330049'),null::jsonb,'already credited snapshot returns no work');
select is((select count(*)::int from loopkit.stamp_events where card_id='00490000-0000-0000-0000-000000000020'),2,'replay does not duplicate events');
select throws_ok($$select loopkit.referral_credit_snapshot('00490000-0000-0000-0000-000000000030','+6594440049')$$,'P0001','invalid referral credit','missing reservation denied');
insert into loopkit.referral_credits(referral_host_id,guest_phone)values('00490000-0000-0000-0000-000000000030','+6595550049');
delete from loopkit.cards where id='00490000-0000-0000-0000-000000000020';
select throws_ok($$select loopkit.referral_credit_snapshot('00490000-0000-0000-0000-000000000030','+6595550049')$$,'P0001','invalid referral state','missing state cannot be computed as zero');
select ok((select credited_at is null from loopkit.referral_credits where referral_host_id='00490000-0000-0000-0000-000000000030' and guest_phone='+6595550049'),'missing state preserves pending reservation');
insert into loopkit.cards(id,program_id,phone,state)values('00490000-0000-0000-0000-000000000020','00490000-0000-0000-0000-000000000010','+6591110049','{}');
select lives_ok($$select * from loopkit.vendor_join_referred('00490000-0000-0000-0000-000000000001','+6596660049','cas-referral')$$,'new referral reserves pending credit');
select lives_ok($$select * from loopkit.vendor_join_referred('00490000-0000-0000-0000-000000000001','+6596660049','cas-referral')$$,'repeated join can return a pending credit');
select is((select guest_count from loopkit.referral_hosts where id='00490000-0000-0000-0000-000000000030'),1,'pending retry does not count guest twice');
update loopkit.programs set type='stamp' where id='00490000-0000-0000-0000-000000000010';
select lives_ok($$select * from loopkit.vendor_join_referred('00490000-0000-0000-0000-000000000001','+6596660049','cas-referral')$$,'pending credit follows current program type under lock');
select lives_ok($$select * from loopkit.vendor_join_referred('00490000-0000-0000-0000-000000000001','+6596660049','cas-referral')$$,'completed stamp retry remains safe');
select is((select stamp_count from loopkit.cards where id='00490000-0000-0000-0000-000000000020'),1,'converted pending credit applies one stamp only');
select * from finish();
rollback;
